import React, {useState,useEffect,useMemo} from 'react';
import {googleFlightsSearchUrl, ORIGIN_AIRPORTS, DESTINATION_AIRPORTS} from './googleFlightsLinks.js';
import {ResponsiveContainer,AreaChart,Area,XAxis,YAxis,CartesianGrid,Tooltip} from 'recharts';
import {Plane,LayoutDashboard,History,Settings2,Sun,Moon,Search,RefreshCw,Mail,
  ArrowUpRight,ArrowDownRight,ChartNoAxesCombined,Clock3,CalendarDays,CheckCircle2,AlertTriangle,
  Globe2,ArrowRight,Filter,Info,Database,ChevronDown,MapPin,ExternalLink,CloudDownload,Menu,
  X,SlidersHorizontal,Navigation,Coins,Bell,ShieldCheck,Wallet,PlaneTakeoff} from 'lucide-react';

const money=n=>n===null||n===undefined?'—':new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:2}).format(n);
const when=s=>s?new Date(s).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'Nunca';
const day=s=>s?new Date(`${s}T12:00:00`).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}):'—';
const TITLES={dashboard:'Visão geral',compare:'Comparador',offers:'Oportunidades',history:'Histórico',google:'Alertas Google',extras:'Custos adicionais',settings:'Configurações'};
const DEST={FCO:'Roma',MXP:'Milão',BGY:'Milão',LIN:'Milão',BCN:'Barcelona',MAD:'Madri'};
const STATIC_MODE=import.meta.env.VITE_STATIC_MODE==='true';
const ACTIONS_URL='https://github.com/PLUSHIAN/atlas_project/actions/workflows/atlas.yml';
const GOOGLE_FLIGHTS_URL='https://www.google.com/travel/flights?hl=pt-BR';
const PLUS_DAYS=(iso,n)=>{const d=new Date(iso+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const destinations=['FCO','MXP','BGY','LIN','BCN','MAD'];
const origins=['GRU','CGH','VCP','GIG','SDU'];
function initials(d){return d==='BCN'?'BC':d==='MAD'?'MD':d==='FCO'?'RM':'MI'}
function Badge({children,tone='neutral'}){return <span className={'badge '+tone}>{children}</span>}
function Empty({icon:Icon=Search,title,description}){return <div className="empty"><div className="empty-icon"><Icon size={27}/></div><h3>{title}</h3><p>{description}</p></div>}
function IconWithTitle({icon:Icon,heading,sub}){return <div className="heading-label"><div className="heading-icon"><Icon size={19}/></div><div><strong>{heading}</strong><span>{sub}</span></div></div>}

export default function App(){
 const [view,setView]=useState('dashboard');const [theme,setTheme]=useState(localStorage.getItem('europa-theme')||'dark');
 const [overview,setOverview]=useState(null);const [offers,setOffers]=useState([]);const [history,setHistory]=useState([]);const [checks,setChecks]=useState([]);const [extras,setExtras]=useState([]);const [snapshots,setSnapshots]=useState([]);
 const [error,setError]=useState('');const [scanNotice,setScanNotice]=useState('');const [busy,setBusy]=useState(false);const [loaded,setLoaded]=useState(false);const [mobileMenu,setMobileMenu]=useState(false);
 const [filter,setFilter]=useState({origin:'',destination:'',date:'',maxPrice:''});
 const [token,setToken]=useState(sessionStorage.getItem('europa-token')||'');
 const [form,setForm]=useState({destination:'BCN',mode:'avião',target_city:'Roma',couple_transfer_brl:'',couple_baggage_brl:'',couple_airport_brl:'',hours_each_way:'',notes:''});
 const [formMessage,setFormMessage]=useState('');
 const [compareMode,setCompareMode]=useState('total');
 const [rankings,setRankings]=useState({international_cheapest:[],best_value:[],lowest_known_total:[],without_additional_costs:[],sample_size:0});
 const [marketReference,setMarketReference]=useState([]);const [diagnostics,setDiagnostics]=useState([]);const [coverageInsights,setCoverageInsights]=useState([]);const [showAllTracking,setShowAllTracking]=useState(false);const [lastExecution,setLastExecution]=useState(null);const [originAirportSelection,setOriginAirportSelection]=useState({'São Paulo':'GRU','Rio de Janeiro':'GIG'});const [destAirportSelection,setDestAirportSelection]=useState({'Milão':'MXP'});
 useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('europa-theme',theme)},[theme]);
 const load=async()=>{try{
  let o,a,h,c,e,s,rankingData,referenceData,diagnosticData,coverageData;
  if(STATIC_MODE){
   const response=await fetch(`${import.meta.env.BASE_URL}atlas-data.json?t=${Date.now()}`,{cache:'no-store'});
   if(!response.ok) throw new Error('Snapshot não publicado');
   const data=await response.json();
   ({overview:o,offers:a,history:h,checks:c,extras:e,snapshots:s,rankings:rankingData,market_reference:referenceData,diagnostics:diagnosticData,coverage_insights:coverageData}=data);setLastExecution(data.last_execution||null);
  }else{
   const responses=await Promise.all(['/api/overview','/api/offers','/api/history','/api/checks','/api/extras','/api/snapshots','/api/rankings','/api/market-reference','/api/diagnostics','/api/coverage-insights'].map(u=>fetch(u)));
   if(responses.some(r=>!r.ok))throw new Error('Servidor indisponível ou resposta inválida');
   [o,a,h,c,e,s,rankingData,referenceData,diagnosticData,coverageData]=await Promise.all(responses.map(r=>r.json()));
  }
  setOverview(o);setOffers(a);setHistory(h);setChecks(c);setExtras(e);setSnapshots(s);setRankings(rankingData);setMarketReference(referenceData);setDiagnostics(diagnosticData);setCoverageInsights(coverageData||[]);setError('');setLoaded(true);
 }catch(e){setError(STATIC_MODE?'Snapshot ainda não publicado. Execute o workflow ATLAS no GitHub Actions.':'Não foi possível conectar ao backend. Confira se o FastAPI está rodando na porta 8000.');setLoaded(true)}};
 useEffect(()=>{load();let id=setInterval(load,45000);return()=>clearInterval(id)},[]);
 const scan=async(city=null)=>{if(STATIC_MODE){setScanNotice('No GitHub Pages, use Actions → ATLAS → Run workflow para pesquisar.');window.open(ACTIONS_URL,'_blank','noopener,noreferrer');return;}setBusy(true);setError('');setScanNotice('');try{
   const response=await fetch('/api/scan',{method:'POST',headers:{'Content-Type':'application/json',...(token?{'X-Api-Token':token}:{})},
     body:JSON.stringify(city?{destination:city}:{})});
   const json=await response.json();if(!response.ok)throw new Error(typeof json.detail==='string'?json.detail:'Falha ao solicitar pesquisa');
   setScanNotice(json.message||'Pesquisa iniciada. Veja o Histórico após a conclusão.');setTimeout(load,2000);
 }catch(e){setError(e.message)}finally{setBusy(false)}};
 const updateExtra=async(e)=>{e.preventDefault();if(STATIC_MODE){setFormMessage('No GitHub Pages, edite config/extras.json no repositório e execute o workflow. O formulário funciona somente no modo local.');return;}setFormMessage('');try{
   const body={...form};for(const field of ['couple_transfer_brl','couple_baggage_brl','couple_airport_brl','hours_each_way'])body[field]=body[field]===''?null:Number(body[field]);
   const r=await fetch('/api/extras',{method:'PUT',headers:{'Content-Type':'application/json',...(token?{'X-Api-Token':token}:{})},body:JSON.stringify(body)});
   const d=await r.json();if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:'Dados inválidos');
   setFormMessage('Estimativa manual salva. Não é uma tarifa consultada.');await load();
 }catch(e){setFormMessage(e.message)}};
 const filtered=useMemo(()=>offers.filter(o=>(!filter.origin||o.origin===filter.origin)&&(!filter.destination||o.destination===filter.destination)
 &&(!filter.date||o.departure===filter.date)&&(!filter.maxPrice||o.price_couple<=Number(filter.maxPrice))),[offers,filter]);
 const chart=useMemo(()=>{
  const grouped={};
  for(const h of history){const key=h.seen_at?.slice(0,10);if(!key)continue;
    grouped[key]??={date:day(key),fullDate:key};grouped[key].price=Math.min(grouped[key].price??Infinity,h.price_couple)}
  for(const h of snapshots){const key=h.seen_at?.slice(0,10);if(!key)continue;
    grouped[key]??={date:day(key),fullDate:key};grouped[key].indicative=Math.min(grouped[key].indicative??Infinity,h.price_couple)}
  return Object.values(grouped).sort((a,b)=>a.fullDate.localeCompare(b.fullDate));
 },[history,snapshots]);
 const recentMarket=useMemo(()=>{
  const unique=new Map();
  for(const x of snapshots){
    const k=[x.origin,x.destination,x.departure,x.return_departure].join('|');
    if(!unique.has(k)||x.price_couple<unique.get(k).price_couple)unique.set(k,x);
  }
  return [...unique.values()].sort((a,b)=>a.price_couple-b.price_couple).slice(0,30);
 },[snapshots]);
 const category=o=>o.price_couple<=6000?'great':o.price_couple<=8000?'good':'over';
 const nav=[{key:'dashboard',icon:LayoutDashboard},{key:'compare',icon:ChartNoAxesCombined},{key:'offers',icon:Plane},{key:'history',icon:History},{key:'google',icon:Bell},{key:'extras',icon:Navigation},{key:'settings',icon:Settings2}];
 const st=overview?.monitor||{};

 const googleTasks=useMemo(()=>{
  const cities=['Barcelona','Madri','Roma','Milão'];
  const groups=[{name:'São Paulo',airports:'GRU, CGH ou VCP'},{name:'Rio de Janeiro',airports:'GIG ou SDU'}];
  const tasks=[];
  for(const city of cities)for(const date of ['2027-09-08','2027-09-09','2027-09-10','2027-09-11']){
    const cover=coverageInsights.find(x=>x.city===city)?.dates?.find(x=>x.departure===date);
    for(const origin of groups)tasks.push({
      id:city+'|'+date+'|'+origin.name,city,date,origin:origin.name,airports:origin.airports,
      back1:PLUS_DAYS(date,15),back2:PLUS_DAYS(date,16),
      checked:cover?.consulted||0,minIndicative:cover?.min_indicative??null
    });
  }
  return tasks.sort((a,b)=>(a.checked>0)-(b.checked>0)||cities.indexOf(a.city)-cities.indexOf(b.city)||a.date.localeCompare(b.date));
 },[coverageInsights]);
 const copyGoogleTask=async(task)=>{
   const str=task.origin+' ('+task.airports+') → '+task.city+' | 2 adultos, econômica | Ida '+task.date+' | Pesquisar voltas '+task.back1+' e '+task.back2+'; verificar chegada ao Brasil e 17 dias corridos.';
   try{await navigator.clipboard.writeText(str);setScanNotice('Rota e datas copiadas. Abra o Google Flights e ative "Acompanhar preços" manualmente.');}
   catch{setScanNotice(str);}
 };

 const topAction=STATIC_MODE?<a className="primary" href={ACTIONS_URL} target="_blank" rel="noopener noreferrer"><ExternalLink size={16}/> Executar no GitHub</a>:<button className="primary" onClick={()=>scan()} disabled={busy||st.running||!st.configured}><RefreshCw size={16} className={busy||st.running?'spin':''}/>{busy||st.running?'Pesquisando...':'Pesquisar próxima'}</button>;
 const item=(n)=>{const Icon=n.icon;return <button key={n.key} className={'nav-item '+(view===n.key?'selected':'')} onClick={()=>{setView(n.key);setMobileMenu(false)}}><Icon size={19}/><span>{TITLES[n.key]}</span>{n.key==='offers'&&offers.length>0?<small>{offers.length}</small>:null}</button>};
 return <div className="shell">
  <aside className={'sidebar '+(mobileMenu?'sidebar-open':'')}>
   <div className="logo"><div className="logo-mark"><PlaneTakeoff size={23}/></div><div><strong>ATLAS<span className="logo-dot">.</span></strong><small>RADAR DE PASSAGENS</small></div><button className="only-mobile close" onClick={()=>setMobileMenu(false)}><X size={20}/></button></div>
   <div className="side-label">ESPAÇO DE TRABALHO</div><nav>{nav.map(item)}</nav>
   <div className="side-spacer"/><div className="trip-compact"><div className="trip-compact-kicker"><CalendarDays size={14}/> SUA VIAGEM</div><strong>Itália, set. 2027</strong><span>08 a 27 de setembro</span><div className="trip-compact-detail"><span><Globe2 size={14}/> 2 adultos</span><span><Clock3 size={14}/> 17 dias</span></div></div>
   <div className="sidebar-bottom"><span className={'status-dot '+(st.running?'working':st.configured?'ready':'off')}/><span>{st.running?'Pesquisa em andamento':st.configured?'Fonte conectada':'Chave da API pendente'}</span></div>
  </aside>
  <div className="main">
   <header className="topbar"><div className="top-left"><button className="icon-button only-mobile" onClick={()=>setMobileMenu(true)}><Menu size={22}/></button><div><div className="breadcrumb">SEU RADAR <span>/</span> <strong>{TITLES[view]}</strong></div><div className="top-sub">Planeje mais. Pague menos.</div></div></div><div className="top-actions"><span className="desktop-status"><span className={'status-dot '+(st.running?'working':st.configured?'ready':'off')}/>{st.running?'Em pesquisa':st.configured?'Monitor pronto':'Configuração pendente'}</span><button className="icon-button" aria-label="Alternar tema" title="Alternar tema" onClick={()=>setTheme(theme==='dark'?'light':'dark')}>{theme==='dark'?<Sun size={19}/>:<Moon size={19}/>}</button>{topAction}</div></header>
   <main className="content">
    {error&&<div className="notice error"><AlertTriangle size={18}/><span>{error}</span><button onClick={()=>setError('')}><X size={18}/></button></div>}
    {scanNotice&&<div className="notice info"><Info size={18}/><span>{scanNotice}</span><button onClick={()=>setScanNotice('')}><X size={18}/></button></div>}
    {STATIC_MODE&&<div className="notice info"><Info size={18}/><span>Modo GitHub Pages: painel de consulta, sem servidor ligado. Workflow agendado a cada 2 horas; para preservar a cota gratuita, as buscas efetivas respeitam o saldo da fonte e o cache. Dados históricos, não ofertas garantidas.</span></div>}
    {STATIC_MODE&&lastExecution&&<div className={'notice '+(lastExecution.status==='erro'?'error':'info')}>
      {lastExecution.searched?<CheckCircle2 size={19}/>:<Info size={19}/>}
      <span><strong>{lastExecution.searched?'Pesquisa real executada':'GitHub executou, mas não houve nova consulta'}</strong>
      {' · '}{when(lastExecution.at)}
      {' · '}{lastExecution.event==='schedule'?'Agendado':lastExecution.event==='push'?'Automático por atualização':'Manual'}
      {lastExecution.destination?' · '+lastExecution.destination:''}
      <small style={{display:'block',marginTop:5}}>{lastExecution.message||'Veja o histórico para detalhes.'}</small>
      </span>{lastExecution.run_id&&<a href={'https://github.com/PLUSHIAN/atlas_project/actions/runs/'+lastExecution.run_id} target="_blank" rel="noopener noreferrer">Ver execução <ExternalLink size={14}/></a>}
     </div>}
    {view==='dashboard'&&<>
      <section className="hero"><div className="hero-copy"><div className="eyebrow"><span className="sparkle">✦</span> SUA PRÓXIMA AVENTURA</div><h1>O melhor caminho<br/>para a <em>Itália.</em></h1><p>Estamos de olho nas passagens para vocês dois. Compare São Paulo, Rio e quatro portas de entrada na Europa, sem perder o controle do orçamento.</p><div className="hero-chips"><span><CalendarDays size={15}/> Setembro de 2027</span><span><Globe2 size={15}/> 2 passageiros</span><span><Wallet size={15}/> Até R$ 8 mil</span></div></div><div className="hero-art" aria-hidden="true"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><span className="big-plane">✈</span><div className="italy-outline">ITALIA</div><div className="art-label">SÃO PAULO / RIO <ArrowRight size={14}/> EUROPA</div></div></section>
      {!STATIC_MODE&&!st.configured&&<div className="notice info"><Info size={18}/><span><strong>Primeiro acesso:</strong> informe a SERPAPI_KEY no <code>.env</code> e reinicie o backend. Nenhuma cotação fictícia é apresentada.</span><button onClick={()=>setView('settings')}>Ver configuração <ArrowRight size={15}/></button></div>}
      <div className="stats-grid">
        <div className="stat-card"><div className="stat-top"><span>MENOR IDA + VOLTA VALIDADA</span><div className="stat-icon blue"><Wallet size={18}/></div></div><strong>{money(overview?.best_price)}</strong><div className="stat-foot"><span className="little-dot"/> 2 adultos • 17 dias confirmados</div></div>
        <div className="stat-card"><div className="stat-top"><span>OPORTUNIDADES</span><div className="stat-icon green"><CheckCircle2 size={18}/></div></div><strong>{overview?.opportunities_count??'—'}</strong><div className="stat-foot">Até R$ 8.000 para o casal</div></div>
        <div className="stat-card"><div className="stat-top"><span>CONSULTAS NOS ÚLTIMOS 30 DIAS</span><div className="stat-icon purple"><Database size={18}/></div></div><strong>{st.used_requests_30d??'—'} <span className="stat-denom">/ {st.max_requests_30d??210}</span></strong><div className="progress"><div style={{width:`${Math.min(100,(st.used_requests_30d||0)/(st.max_requests_30d||210)*100)}%`}}/></div><div className="stat-foot">Limite local de segurança</div></div>
        <div className="stat-card"><div className="stat-top"><span>ÚLTIMA PESQUISA</span><div className="stat-icon amber"><Clock3 size={18}/></div></div><strong className="small-stat">{when(overview?.last_scan_at)}</strong><div className="stat-foot">A cada {st.interval_hours||2}h; no Pages, via GitHub Actions</div></div>
      </div>

      <div className="notice info"><Info size={19}/><span><strong>Cobertura real do radar:</strong> {overview?.coverage?.consulted??0} de {overview?.coverage?.total??64} combinações agrupadas consultadas. Ainda faltam {overview?.coverage?.not_yet_consulted??64}. Cada combinação representa um grupo de aeroportos, não todos os aeroportos individualmente. <strong>Menor custo parcial conhecido até a Itália:</strong> {money(overview?.best_total_known)}. Compare as opções em <button className="inline-link" onClick={()=>setView('compare')}>Comparador</button>. Bagagem e outros custos podem faltar.</span></div>
      <section className="panel city-panel">
       <div className="panel-head"><div><div className="section-kicker">RODÍZIO DE DESTINOS</div><h2>Espanha em prioridade + Itália multidestinos</h2></div><Badge>Próxima no rodízio: {st.next_destination||'—'}</Badge></div>
       <p className="muted note">Com SPAIN_PRIORITY=true, 2 de cada 3 rodadas automáticas são para Barcelona ou Madri; Roma, Milão e Roma ↔ Milão também são monitoradas. A prioridade não indica que Espanha seja sempre mais barata. Você pode escolher manualmente qualquer modalidade. Cada clique pode usar de 1 a 3 créditos gratuitos; preços indicativos não são ofertas confirmadas.</p>
       <div className="city-grid">{(st.city_coverage||[]).map(city=><div className="city-card" key={city.city}><div className="city-card-top"><strong>{city.city}</strong><Badge tone={city.consulted>0?'green':'neutral'}>{city.consulted>0?'Consultado':city.attempted>0?'Tentativa sem sucesso':'Não consultado'}</Badge></div><div className="city-card-meta">{city.consulted} de {city.total} combinações consultadas</div><small>{city.last_checked?'Última tentativa: '+when(city.last_checked):'Nenhuma tentativa registrada'}</small><button className="outline" onClick={()=>scan(city.city)} disabled={busy||st.running||!st.configured}>Pesquisar {city.city}</button></div>)}</div>
       <p className="muted city-footnote">Milão inclui MXP, BGY e LIN. As origens também são agrupadas. Uma pesquisa pode não retornar todas as opções do grupo.</p>
      </section>
      <section className="panel insight-panel">
       <div className="panel-head"><div><div className="section-kicker">COBERTURA POR CIDADE E DATA</div><h2>Quais preços já vimos e o que falta pesquisar?</h2></div><button className="link-button" onClick={()=>setView('google')}>Alertas gratuitos do Google <ArrowRight size={15}/></button></div>
       <p className="muted note">Os números representam combinações agrupadas de aeroportos, não todos os voos individuais. Prévia é apenas indicativa, sem volta validada. O preço de ida e volta validado aparece separado.</p>
       <div className="insight-grid">{coverageInsights.filter(x=>['Barcelona','Madri','Roma','Milão'].includes(x.city)).sort((a,b)=>['Barcelona','Madri','Roma','Milão'].indexOf(a.city)-['Barcelona','Madri','Roma','Milão'].indexOf(b.city)).map(x=><div className="insight-card" key={x.city}>
        <div className="insight-card-head"><strong>{x.city}</strong><Badge tone={x.consulted?'green':'neutral'}>{x.dates_covered}/{x.dates_total} datas</Badge></div>
        <div className="insight-price"><span>Menor ida + volta validada</span><strong>{money(x.min_complete)}</strong></div>
        <div className="insight-price"><span>Menor prévia observada</span><strong>{money(x.min_indicative)}</strong></div>
        <small className="muted">{x.consulted}/{x.total} combinações agrupadas · {x.sample_size} prévias</small>
        <div className="date-coverage">{x.dates.map(d=><div className="date-coverage-row" key={d.departure}><span>{day(d.departure)} · {d.consulted}/{d.total}</span><strong>{money(d.min_indicative)}</strong></div>)}</div>
        <small className="muted">{x.last_attempt?'Última tentativa: '+when(x.last_attempt):'Ainda não pesquisada'}</small>
       </div>)}</div>
      </section>
      <section className="panel market-panel">
       <div className="panel-head"><div><div className="section-kicker">REFERÊNCIA DE MERCADO</div><h2>Quanto estão custando as passagens?</h2></div><button className="link-button" onClick={()=>setView('history')}>Ver todas as prévias <ArrowRight size={15}/></button></div>
       <p className="muted market-explain">As menores prévias entre as últimas 150 observações são exibidas abaixo. A prévia é o preço exibido pela SerpApi na primeira etapa da busca de ida e volta para <strong>2 adultos</strong>. Ainda não confirma uma combinação de voos que satisfaça os 17 dias. Valores acima de R$ 8.000 também são registrados. Nenhuma prévia gera alerta.</p>
       <div className="market-hero"><div><span>MENOR PRÉVIA OBSERVADA</span><strong>{money(overview?.indicative_min_price)}</strong><small>Histórico das datas efetivamente pesquisadas • não é preço de compra confirmado</small></div><div><span>PRÉVIAS REGISTRADAS</span><strong>{overview?.indicative_count??0}</strong><small>Tarifas indicativas, inclusive fora do orçamento</small></div></div>
       {recentMarket.length?<div className="market-list">{recentMarket.slice(0,6).map(x=><div className="market-item" key={x.id}><div><strong>{x.origin} → {x.destination}</strong><small>Ida {day(x.departure)} · retorno previsto {day(x.return_departure)} · {when(x.seen_at)}</small></div><div className="market-price"><strong>{money(x.price_couple)}</strong><Badge tone="neutral">Indicativo</Badge></div></div>)}</div>:<Empty icon={Search} title="Ainda não há base de preços" description="Na próxima pesquisa com tarifas retornadas, você verá aqui os valores indicativos, mesmo acima do orçamento."/>}
      </section>
      <div className="dual-grid"><section className="panel chart-panel"><div className="panel-head"><div><div className="section-kicker">ANÁLISE DE PREÇOS</div><h2>Evolução de preços verificados e indicativos</h2></div><Badge>Histórico observado</Badge></div>
       {chart.length?<div className="chart-holder"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chart} margin={{top:14,right:8,left:4,bottom:2}}><defs><linearGradient id="priceShade" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#5577e9" stopOpacity={.25}/><stop offset="95%" stopColor="#5577e9" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="var(--chart-grid)" strokeDasharray="3 5" vertical={false}/><XAxis dataKey="date" tickLine={false} axisLine={false} tick={{fill:'var(--muted)',fontSize:11}}/><YAxis tickLine={false} axisLine={false} tick={{fill:'var(--muted)',fontSize:11}} tickFormatter={v=>'R$ '+Math.round(v/1000)+'k'} width={56}/><Tooltip contentStyle={{background:'var(--surface)',border:'1px solid var(--border)',borderRadius:12,color:'var(--text)'}} formatter={(v,name)=>[money(v),name==='indicative'?'Prévia sem volta validada':'Viagem completa validada']}/><Area type="monotone" connectNulls dataKey="indicative" name="indicative" stroke="#e2a66b" strokeDasharray="6 5" strokeWidth={2} fill="none" dot={chart.length<8}/><Area type="monotone" connectNulls dataKey="price" name="price" stroke="#617dee" strokeWidth={3} fill="url(#priceShade)" dot={chart.length<8}/></AreaChart></ResponsiveContainer></div>:<Empty icon={ChartNoAxesCombined} title="O gráfico começa com sua primeira pesquisa" description="Inclui prévias de valores mesmo quando nenhuma volta de 17 dias for validada."/>}</section>
       <section className="panel activity-panel"><div className="panel-head"><div><div className="section-kicker">ACOMPANHAMENTO</div><h2>Atividade recente</h2></div><button className="link-button" onClick={()=>setView('history')}>Ver tudo <ArrowRight size={15}/></button></div>
        {checks.length?<div className="activity-list">{checks.slice(0,6).map(c=><div className="activity" key={c.id}><span className={'activity-icon '+(c.status==='erro'?'red':c.status==='cotado'?'green':'blue')}>{c.status==='erro'?<AlertTriangle size={16}/>:c.status==='cotado'?<CheckCircle2 size={16}/>:<Search size={16}/>}</span><div><strong>{c.status==='cotado'?'Pesquisa com resultados':c.status==='erro'?'Consulta interrompida':'Pesquisa concluída'}</strong><p>{c.route_key.split('|')[1]?.replaceAll(',',' / ')} · {c.note}</p></div><time>{when(c.checked_at)}</time></div>)}</div>:<Empty icon={History} title="Nenhuma consulta realizada" description="Clique em “Pesquisar agora” depois de configurar sua chave gratuita."/>}</section></div>
      <section className="panel"><div className="panel-head"><div><div className="section-kicker">MELHORES DESCOBERTAS</div><h2>Oportunidades em destaque</h2></div><button className="link-button" onClick={()=>setView('offers')}>Todas as ofertas <ArrowRight size={15}/></button></div>{offers.length?<div className="offers-list">{offers.slice(0,4).map(offerRow)}</div>:<Empty icon={PlaneTakeoff} title="As melhores ofertas aparecerão aqui" description="As prévias de preços já aparecem acima e na aba Histórico. As viagens completas aparecerão após validar a volta."/>}</section>
    </>}
    {view==='compare'&&<>
      <section className="page-intro"><div><div className="section-kicker">COMPARAÇÃO INTELIGENTE · 2 ADULTOS · SETEMBRO 2027</div><h1>Compare antes de comprar</h1><p>Dois rankings diferentes: menor passagem internacional e melhor custo-benefício estimado. Não existe preço inventado nem garantia de disponibilidade.</p></div><Badge tone="blue">{rankings.sample_size||0} itinerários validados</Badge></section>
      <div className="notice info"><Info size={18}/><span>As pesquisas da Espanha têm prioridade porque podem ser mais baratas, mas só vencerão no custo conhecido até a Itália quando você informar os adicionais. No multidestinos Roma ↔ Milão também falta o transporte interno. Nota de custo-benefício é uma heurística, não previsão de preço.</span></div>
      <div className="dual-grid">
       <section className="panel"><div className="panel-head"><div><div className="section-kicker">RANKING 1 · APENAS BILHETE INTERNACIONAL</div><h2>Passagens internacionais mais baratas</h2></div><Badge>{rankings.international_cheapest.length} opções</Badge></div>
         {rankings.international_cheapest.length?<div className="rank-list">{rankings.international_cheapest.slice(0,12).map((x,i)=><div className="rank-item" key={x.id}><span className="rank-num">{i+1}</span><div><strong>{x.origin} → {x.destination}{x.journey_type==='open_jaw'?' / '+x.return_origin:''}</strong><small>{day(x.departure)}–{day(x.arrival_home)} · {x.airline}</small></div><div className="rank-amount"><strong>{money(x.price_couple)}</strong><small>{x.price_couple<=8000?'No orçamento internacional':'Acima da meta'}</small></div></div>)}</div>:<Empty icon={Plane} title="Ainda sem viagem completa" description="Prévia indicativa não entra no ranking. Pesquise outros destinos e consulte o histórico."/>}
       </section>
       <section className="panel"><div className="panel-head"><div><div className="section-kicker">RANKING 2 · GASTOS CONHECIDOS + CONFORTO</div><h2>Menor custo até a Itália</h2></div><Badge>{rankings.lowest_known_total.length} comparáveis</Badge></div>
         <div className="rank-tabs"><button type="button" className={compareMode==='total'?'rank-tab active':'rank-tab'} onClick={()=>setCompareMode('total')}>Menor custo parcial</button><button type="button" className={compareMode==='value'?'rank-tab active':'rank-tab'} onClick={()=>setCompareMode('value')}>Melhor custo-benefício</button></div>
         {rankings.lowest_known_total.length?<div className="rank-list">{(compareMode==='total'?rankings.lowest_known_total:rankings.best_value).slice(0,12).map((x,i)=><div className="rank-item" key={x.id}><span className="score-circle">{x.value_score}</span><div><strong>{x.origin} → {x.destination}{x.journey_type==='open_jaw'?' / '+x.return_origin:''}</strong><small>{x.stops_out} escala(s) ida · {x.stops_back} volta · {x.total_basis==='somente_passagem_internacional'?'Sem transporte adicional internacional':'Inclui estimativa MANUAL'}</small><small>{x.value_reasons?.slice(0,2).join(' · ')||'Sem penalidade identificada'}</small></div><div className="rank-amount"><strong>{money(x.comparable_total)}</strong><small>Custo parcial conhecido</small></div></div>)}</div>:<Empty icon={Wallet} title="Sem custo comparável" description="Informe transporte e bagagens extras quando necessário. Cotações incompletas não recebem nota."/>}
       </section>
      </div>
      {rankings.without_additional_costs.length>0&&<section className="panel"><div className="panel-head"><h2>Viagens excluídas do ranking de custo-benefício</h2><Badge tone="neutral">Custos adicionais faltando</Badge></div><div className="rank-list">{rankings.without_additional_costs.slice(0,12).map(x=><div className="rank-item" key={x.id}><AlertTriangle size={16}/><div><strong>{x.origin} → {x.destination}{x.return_origin&&x.journey_type==='open_jaw'?' / '+x.return_origin:''}</strong><small>Transporte até ou dentro da Itália ainda sem custo informado</small></div><strong>{money(x.price_couple)} (só internacional)</strong></div>)}</div><button className="outline" onClick={()=>setView('extras')}>Informar custos adicionais</button></section>}
      <section className="panel"><div className="panel-head"><div><div className="section-kicker">FONTE: SUA AMOSTRA DE PESQUISAS</div><h2>Base de preços por cidade</h2></div><Badge>Indicativo ≠ oferta</Badge></div><p className="muted note">Preço mínimo, mediano e máximo das prévias recebidas para datas consultadas. Não é média de mercado. Mudança só aparece quando existem consultas em dias diferentes.</p><div className="table-scroll"><table><thead><tr><th>Cidade</th><th>Prévias</th><th>Menor prévia</th><th>Mediana</th><th>Maior prévia</th><th>Melhor completa</th><th>Evolução</th></tr></thead><tbody>{marketReference.map(x=><tr key={x.city}><td><strong>{x.city}</strong></td><td>{x.sample_size}</td><td>{money(x.min_indicative)}</td><td>{money(x.median_indicative)}</td><td>{money(x.max_indicative)}</td><td>{money(x.best_complete)}</td><td>{x.change_brl===null?'Aguardando novos dias':`${x.change_brl>0?'+':''}${money(x.change_brl)}`}</td></tr>)}</tbody></table></div></section>
      <section className="panel"><div className="panel-head"><div><div className="section-kicker">AUDITORIA DAS BUSCAS</div><h2>Por que não encontrei uma tarifa completa?</h2></div><Badge>{diagnostics.length} registros</Badge></div><div className="diagnostic-list">{diagnostics.length?diagnostics.slice(0,18).map(d=><div className="diagnostic-item" key={d.check_id}><div><strong>{d.city||'Rota'} · {d.mode==='open_jaw'?'Multidestinos':'Ida e volta'}</strong><small>{when(d.checked_at)} · {d.api_requests} consultas à API · {d.status}</small></div><div className="diagnostic-stats"><span>{d.metrics?.received_first_stage??0} resultados iniciais</span><span>{d.metrics?.indicative_prices_recorded??0} prévias</span><span>{d.metrics?.return_candidates??0} retornos</span><span>{d.metrics?.complete_itineraries??0} validadas</span>{Object.entries(d.metrics?.rejections||{}).map(([k,v])=><small key={k}>{k.replaceAll('_',' ')}: {v}</small>)}{d.metrics?.followup_error&&<small>{d.metrics.followup_error}</small>}</div></div>):<Empty icon={Search} title="Sem diagnósticos ainda" description="Após a primeira pesquisa da v4, os motivos de descarte aparecerão aqui."/>}</div></section>
    </>}
    {view==='offers'&&<><section className="page-intro"><div><div className="section-kicker">COMPARE ANTES DE COMPRAR</div><h1>Viagens completas encontradas</h1><p>Ranking pelo menor custo conhecido: tarifa internacional para Itália; Espanha apenas se os custos adicionais tiverem sido informados. Valores acima do orçamento também aparecem. Não representa o menor preço de todo o mercado, apenas das combinações verificadas.</p></div><Badge tone="blue">{filtered.length} resultados</Badge></section><section className="filter-bar"><div className="filter-title"><SlidersHorizontal size={18}/> Filtros</div><label>Origem<select value={filter.origin} onChange={e=>setFilter({...filter,origin:e.target.value})}><option value="">Todas</option>{origins.map(x=><option key={x}>{x}</option>)}</select></label><label>Destino<select value={filter.destination} onChange={e=>setFilter({...filter,destination:e.target.value})}><option value="">Todos</option>{destinations.map(x=><option key={x} value={x}>{DEST[x]} · {x}</option>)}</select></label><label>Data da ida<input type="date" min="2027-09-08" max="2027-09-11" value={filter.date} onChange={e=>setFilter({...filter,date:e.target.value})}/></label><label>Até<select value={filter.maxPrice} onChange={e=>setFilter({...filter,maxPrice:e.target.value})}><option value="">Sem limite</option><option value="6000">R$ 6.000</option><option value="8000">R$ 8.000</option><option value="10000">R$ 10.000</option><option value="15000">R$ 15.000</option></select></label><button className="clear-btn" onClick={()=>setFilter({origin:'',destination:'',date:'',maxPrice:''})}>Limpar</button></section>
    <div className="offers-list bordered">{filtered.length?filtered.map(offerRow):<Empty icon={Search} title="Nenhuma cotação para esses filtros" description="Experimente limpar os filtros ou realizar uma pesquisa com a API configurada."/>}</div></>}
    {view==='history'&&<><section className="page-intro"><div><div className="section-kicker">REGISTRO TRANSPARENTE</div><h1>Histórico de pesquisas</h1><p>Todos os preços aqui são registros de consultas anteriores, não garantias de compra agora.</p></div></section><div className="dual-grid"><section className="panel chart-panel"><div className="panel-head"><h2>Evolução de preços</h2><Badge>Histórico</Badge></div>{chart.length?<div className="chart-holder"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chart}><CartesianGrid stroke="var(--chart-grid)" vertical={false}/><XAxis dataKey="date" tick={{fill:'var(--muted)'}}/><YAxis tickFormatter={v=>Math.round(v/1000)+'k'} tick={{fill:'var(--muted)'}}/><Tooltip formatter={v=>money(v)}/><Area dataKey="indicative" name="Prévia (sem volta verificada)" connectNulls stroke="#e2a66b" strokeDasharray="6 5" fill="none"/><Area dataKey="price" name="Volta validada" connectNulls stroke="#617dee" strokeWidth={2} fill="#617dee" fillOpacity={.12}/></AreaChart></ResponsiveContainer></div>:<Empty title="Sem histórico" description="Nenhuma pesquisa retornou uma cotação válida."/>}</section><section className="panel"><div className="panel-head"><h2>Últimas verificações</h2><Badge>{checks.length} registros recentes</Badge></div><div className="check-table">{checks.length?checks.map(c=><div className="check-row" key={c.id}><span className="check-time">{when(c.checked_at)}</span><div><strong>{c.route_key.split('|').slice(0,2).join(' → ')}</strong><small>{c.note}</small></div><Badge tone={c.status==='erro'?'red':c.status==='cotado'?'green':'neutral'}>{c.status}</Badge></div>):<Empty title="Nenhuma verificação" description="As pesquisas executadas aparecem aqui."/>}</div></section></div><section className="panel history-table"><div className="panel-head"><div><h2>Snapshots indicativos de mercado</h2><p className="muted">Preços da primeira etapa da SerpApi, sem retorno individual confirmado. Inclui tarifas acima do orçamento.</p></div><Badge>{snapshots.length} registros recentes</Badge></div><div className="table-scroll"><table><thead><tr><th>Consultado em</th><th>Rota</th><th>Ida</th><th>Volta prevista</th><th>Preço indicativo / casal</th><th>Validação</th><th>Conferir</th></tr></thead><tbody>{snapshots.length?snapshots.map(x=><tr key={x.id}><td>{when(x.seen_at)}</td><td>{x.origin} → {x.destination}</td><td>{day(x.departure)}</td><td>{day(x.return_departure)}</td><td><strong>{money(x.price_couple)}</strong></td><td>Volta ainda não validada</td><td><a href={x.search_url} target="_blank" rel="noreferrer">Google Flights</a></td></tr>):<tr><td colSpan="7" className="nothing">Sem prévias retornadas pela API ainda.</td></tr>}</tbody></table></div></section><section className="panel history-table"><div className="panel-head"><h2>Viagens completas validadas</h2><span className="muted">Cada linha é uma observação histórica da API</span></div><div className="table-scroll"><table><thead><tr><th>Consultado em</th><th>Rota</th><th>Saída</th><th>Retorno</th><th>Preço / casal</th><th>Origem dos dados</th></tr></thead><tbody>{history.length?history.map((h,i)=><tr key={i}><td>{when(h.seen_at)}</td><td>{h.origin} → {h.destination}</td><td>{day(h.departure)}</td><td>{day(h.return_departure)}</td><td><strong>{money(h.price_couple)}</strong></td><td>SerpApi / Google Flights</td></tr>):<tr><td colSpan="6" className="nothing">Sem cotações históricas ainda.</td></tr>}</tbody></table></div></section></>}
    {view==='google'&&<>
      <section className="page-intro"><div><div className="section-kicker">SEGUNDA FONTE GRATUITA</div><h1>Alertas oficiais do Google Flights</h1><p>Configure os acompanhamentos na sua conta Google. O Google envia avisos ao seu e-mail; o ATLAS não consulta nem automatiza o site.</p></div><Badge tone="blue">Sem créditos SerpApi</Badge></section>
      <div className="notice info"><Info size={19}/><span>Os botões de volta abrem uma pesquisa com aeroporto e datas já informados. <strong>Os avisos oficiais NÃO são ativados automaticamente.</strong> Entre na sua conta Google e clique em “Acompanhar preços” para cada rota e data. O Google decide quando enviar notificações e não garante frequência.</span></div>
      <section className="panel">
       <div className="panel-head"><div><div className="section-kicker">COMO ATIVAR</div><h2>Receba avisos diretamente no Gmail</h2></div><a className="outline" href={GOOGLE_FLIGHTS_URL} target="_blank" rel="noopener noreferrer"><ExternalLink size={16}/> Abrir Google Flights</a></div>
       <div className="google-instructions">
        <div><strong>1. Entre na sua conta Google</strong><small>Abra o Google Flights e selecione ida e volta, econômica, 2 adultos.</small></div>
        <div><strong>2. Abra a busca pronta</strong><small>Escolha a origem no ATLAS e clique em uma das datas de volta. Confira no Google Flights os filtros aplicados e a chegada ao Brasil em 17 dias.</small></div>
        <div><strong>3. Ative “Acompanhar preços”</strong><small>Habilite o acompanhamento para as datas selecionadas. Você também pode testar “Qualquer data” como complemento.</small></div>
        <div><strong>4. Confira os avisos no Gmail</strong><small>O Google notifica mudanças relevantes; confirme tarifa final, taxas, bagagem e trecho Espanha–Itália antes de comprar.</small></div>
       </div>
       <p className="muted note">Para cada ida abaixo, confira partidas da Europa em D+15 e D+16. Somente a chegada ao Brasil em D+16 respeita os 17 dias corridos. Os avisos do Google não alimentam automaticamente o histórico do ATLAS.</p>
       <a href="https://support.google.com/travel/answer/6235879?hl=pt-BR" target="_blank" rel="noopener noreferrer">Ajuda oficial: acompanhar voos e preços <ExternalLink size={13}/></a>
      </section>
      <section className="panel">
       <div className="panel-head"><div><div className="section-kicker">ROTEIRO PARA ATIVAR ALERTAS</div><h2>Rotas e datas para acompanhar</h2></div><Badge>{googleTasks.length} combinações sugeridas</Badge></div>
       <p className="muted note">Primeiro aparecem as combinações com menos consultas registradas. Escolha o aeroporto e clique na data de volta desejada: o Google Flights abre com rota, datas e moeda na busca. Confira se o Google aplicou 2 adultos antes de ativar o alerta.</p>
       <div className="tracking-grid">{googleTasks.slice(0,showAllTracking?googleTasks.length:8).map(task=><div className="tracking-card" key={task.id}>
        <div className="tracking-head"><strong>{task.origin} → {task.city}</strong><Badge tone={task.checked?'green':'neutral'}>{task.checked?'Prévia no ATLAS':'Sem prévia no ATLAS'}</Badge></div>
        <div className="tracking-airport-selectors">
         <label>Saindo de
          <select value={originAirportSelection[task.origin]} onChange={e=>setOriginAirportSelection(prev=>({...prev,[task.origin]:e.target.value}))}>
           {ORIGIN_AIRPORTS[task.origin].map(code=><option value={code} key={code}>{code}</option>)}
          </select>
         </label>
         <label>Chegando em
          <select value={destAirportSelection[task.city]||DESTINATION_AIRPORTS[task.city][0]} onChange={e=>setDestAirportSelection(prev=>({...prev,[task.city]:e.target.value}))}>
           {DESTINATION_AIRPORTS[task.city].map(code=><option value={code} key={code}>{code}</option>)}
          </select>
         </label>
        </div>
        <span>Ida: <strong>{day(task.date)}</strong> · 2 adultos · econômica · BRL</span>
        <small>Menor prévia da data pesquisada pelo ATLAS: {money(task.minIndicative)}</small>
        <div className="tracking-actions">
         <a className="outline" href={googleFlightsSearchUrl({originCity:task.origin,originAirport:originAirportSelection[task.origin],destinationCity:task.city,destinationAirport:destAirportSelection[task.city]||DESTINATION_AIRPORTS[task.city][0],departure:task.date,returnDate:task.back1})} target="_blank" rel="noopener noreferrer">Volta {day(task.back1)} <ExternalLink size={14}/></a>
         <a className="outline" href={googleFlightsSearchUrl({originCity:task.origin,originAirport:originAirportSelection[task.origin],destinationCity:task.city,destinationAirport:destAirportSelection[task.city]||DESTINATION_AIRPORTS[task.city][0],departure:task.date,returnDate:task.back2})} target="_blank" rel="noopener noreferrer">Volta {day(task.back2)} <ExternalLink size={14}/></a>
        </div>
       </div>)}</div>
       <button className="outline" style={{marginTop:16}} onClick={()=>setShowAllTracking(v=>!v)}>{showAllTracking?'Mostrar apenas 8':'Ver todas as 32 sugestões'}</button>
      </section>
    </>}
    {view==='extras'&&<><section className="page-intro"><div><div className="section-kicker">CONEXÕES E TRANSPORTES INTERNOS</div><h1>Deslocamentos adicionais</h1><p>Planeje os trechos Espanha–Itália e Roma–Milão e registre os custos manualmente. Esses valores são estimativas suas, nunca preços verificados pela API.</p></div></section>
    <div className="notice info"><Info size={19}/><span>Barcelona e Madri têm prioridade nas pesquisas internacionais, mas Roma e Milão continuam no ciclo. O bilhete multidestinos exige transporte interno entre as cidades italianas. O limite de R$ 8.000 considera <strong>somente o voo internacional</strong>. Não há integração gratuita comprovada para cotar automaticamente os trechos Espanha–Itália, por isso não inventamos valores ou tempos.</span></div>
    <div className="dual-grid"><section className="panel form-panel"><div className="panel-head"><div><div className="section-kicker">ESTIMATIVA PERSONALIZADA</div><h2>Adicionar um trajeto</h2></div><Coins size={19} className="muted"/></div><form onSubmit={updateExtra}><div className="form-grid"><label>Deslocamento necessário<select value={form.destination} onChange={e=>setForm({...form,destination:e.target.value,target_city:e.target.value==='ROM_MIL'?'Milão':e.target.value==='MIL_ROM'?'Roma':form.target_city})}><option value="BCN">Barcelona → Itália</option><option value="MAD">Madri → Itália</option><option value="ROM_MIL">Roma → Milão (transporte interno)</option><option value="MIL_ROM">Milão → Roma (transporte interno)</option></select></label><label>Destino do deslocamento<select value={form.target_city} onChange={e=>setForm({...form,target_city:e.target.value})}><option>Roma</option><option>Milão</option></select></label><label>Meio de transporte<select value={form.mode} onChange={e=>setForm({...form,mode:e.target.value})}><option>avião</option><option>trem</option><option>ônibus</option><option>outro</option></select></label><label>Tempo estimado, horas do deslocamento<input type="number" min="0" step="0.25" placeholder="Não informado" value={form.hours_each_way} onChange={e=>setForm({...form,hours_each_way:e.target.value})}/></label><label>Custo total dos bilhetes adicionais para o casal (R$)<input type="number" min="0" step="0.01" placeholder="Informe somente após pesquisar" value={form.couple_transfer_brl} onChange={e=>setForm({...form,couple_transfer_brl:e.target.value})}/></label><label>Bagagens adicionais do casal (R$)<input type="number" min="0" step="0.01" placeholder="Não informado" value={form.couple_baggage_brl} onChange={e=>setForm({...form,couple_baggage_brl:e.target.value})}/></label><label>Translado entre aeroportos do casal (R$)<input type="number" min="0" step="0.01" placeholder="Não informado" value={form.couple_airport_brl} onChange={e=>setForm({...form,couple_airport_brl:e.target.value})}/></label><label className="wide">Anotações<input maxLength={400} placeholder="Ex.: orçamento verificado manualmente em determinada data" value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></label></div><button className="primary full" type="submit" disabled={STATIC_MODE}><CheckCircle2 size={17}/> Salvar estimativa manual</button>{formMessage&&<div className="form-message">{formMessage}</div>}</form></section>
    <section className="panel form-panel"><div className="panel-head"><div><div className="section-kicker">COMPARAÇÃO REALISTA</div><h2>Trajetos registrados</h2></div><Badge>{extras.length} estimativas</Badge></div><p className="muted note">Valores incompletos permanecem indisponíveis. É necessário orçar a ida e a volta, além de bagagens e translados, para o custo final aparecer.</p>{extras.length?<div className="saved-list">{extras.map((x,i)=>{const parts=[x.couple_transfer_brl,x.couple_baggage_brl,x.couple_airport_brl];const total=parts.every(v=>v!==null)?parts.reduce((a,b)=>a+b,0):null;return <div className="saved-extra" key={i}><div><strong>{x.destination} → {x.target_city}</strong><small>Via {x.mode} • {x.hours_each_way==null?'Tempo não informado':`${x.hours_each_way}h por trecho`} • estimativa manual</small></div><strong>{money(total)}</strong></div>})}</div>:<Empty icon={Navigation} title="Nenhuma estimativa adicionada" description="Pesquise preços de transferências nos sites oficiais e registre o que encontrar."/>}</section></div></>}
    {view==='settings'&&<><section className="page-intro"><div><div className="section-kicker">CONTROLE DO MONITORAMENTO</div><h1>Configuração e limites</h1><p>As credenciais ficam no arquivo .env do backend, nunca são exibidas no painel.</p></div></section>
      <div className="settings-grid"><section className="panel settings-panel"><IconWithTitle icon={ShieldCheck} heading="API e fonte de dados" sub="SerpApi / Google Flights"/><div className="setting-row"><span>Chave configurada</span><Badge tone={st.configured?'green':'amber'}>{st.configured?'Sim':'Não'}</Badge></div><div className="setting-row"><span>Plano</span><strong>{st.quota?.plan_name||'Não identificado'}</strong></div><div className="setting-row"><span>Consultas restantes no plano</span><strong>{st.quota?.plan_searches_left??'Indisponível'}</strong></div><div className="setting-row"><span>Limite mensal informado pela API</span><strong>{st.quota?.searches_per_month??'Indisponível'}</strong></div><div className="setting-row"><span>Requisições locais em 30 dias</span><strong>{st.used_requests_30d??0} / {st.max_requests_30d||210}</strong></div><div className="setting-row"><span>Intervalo do agendamento</span><strong>{st.interval_hours||6} horas{STATIC_MODE?' (consultas limitadas pela cota)':''}</strong></div></section>
      <section className="panel settings-panel"><IconWithTitle icon={Bell} heading="Alertas por e-mail" sub="SMTP gratuito, sem envio de mensagens de teste"/><div className="setting-row"><span>SMTP pronto</span><Badge tone={st.smtp_ready?'green':'amber'}>{st.smtp_ready?'Configurado':'Pendente'}</Badge></div><div className="setting-row"><span>Até R$ 6.000</span><Badge tone="green">Excelente oportunidade</Badge></div><div className="setting-row"><span>Até R$ 8.000</span><Badge tone="blue">Dentro do orçamento</Badge></div><div className="setting-row"><span>Acima de R$ 8.000</span><strong>Sem alerta</strong></div><div className="setting-row"><span>Reenvio após queda relevante</span><strong>5% e R$ 200 (padrão)</strong></div></section>
      <section className="panel settings-panel"><IconWithTitle icon={Database} heading="Privacidade e proteção" sub="SQLite local e requisições contabilizadas"/><div className="setting-row"><span>Fonte de tarifas</span><strong>Somente SerpApi</strong></div><div className="setting-row"><span>Valores estimados</span><strong>Identificados separadamente</strong></div><div className="setting-row"><span>Persistência</span><strong>SQLite</strong></div><div className="setting-row"><span>Pesquisas automáticas</span><Badge tone={st.enabled?'green':'neutral'}>{st.enabled?'Ativas com backend':'Desabilitadas'}</Badge></div><div className="setting-row"><span>Modo de busca</span><strong>{st.search_mode||'Rodízio'} • {st.route_count||64} combinações</strong></div></section>
      <section className="panel settings-panel"><IconWithTitle icon={Settings2} heading="Acesso administrativo" sub="Se configurou APP_API_TOKEN no .env"/><p className="muted note">Este token fica apenas na sessão atual do navegador e permite iniciar buscas e salvar estimativas.</p><label className="token-label">Token de administração<input type="password" value={token} placeholder="Deixe vazio se não estiver configurado" onChange={e=>{setToken(e.target.value);sessionStorage.setItem('europa-token',e.target.value)}}/></label><div className="setting-row"><span>Último erro registrado</span><strong className="err-text">{st.last_error||'Nenhum'}</strong></div><button className="outline full" onClick={load}><RefreshCw size={16}/> Atualizar status</button></section></div>
      <div className="notice info"><Info size={19}/><span>O backend acompanha combinações agrupadas de datas e regiões e pode pesquisar ida Roma, volta Milão ou o inverso. A rotação prioriza Espanha, mas uma consulta agrupada não garante que o Google Flights devolva preços para cada aeroporto individualmente. Confira o README para limitações e instalação.</span></div></>}
    <footer className="footer"><span>ATLAS • Projeto pessoal · Europa 2027</span><span>Todos os preços devem ser confirmados antes da compra <ShieldCheck size={15}/></span></footer>
   </main>
  </div>
 </div>;
 function offerRow(o){return <div className="offer" key={o.id}><div className="offer-icon">{initials(o.destination)}</div><div className="offer-main"><div className="offer-route"><strong>{o.origin} <ArrowRight size={15}/> {o.destination}{o.journey_type==='open_jaw'?' / '+o.return_origin:''}</strong><Badge tone={category(o)==='great'?'green':category(o)==='good'?'blue':'neutral'}>{category(o)==='great'?'Excelente oportunidade':category(o)==='good'?'Dentro do orçamento':'Acima do orçamento'}</Badge></div><div className="offer-sub">{DEST[o.destination]} · {day(o.departure)} a {day(o.arrival_home)} · {o.airline||'Companhia não informada'}</div><div className="offer-tags"><span><Plane size={13}/>{o.stops_out} escala(s) ida / {o.stops_back} volta</span><span><Clock3 size={13}/> Consultado {when(o.seen_at)}</span>{o.extras?.length>0&&<span><Info size={13}/> Itália: {o.extras[0].estimated_total==null?'custo adicional não disponível':money(o.extras[0].estimated_total)+' (manual)'}</span>}{o.warnings?.map((warning,i)=><span key={i}><AlertTriangle size={13}/> {warning}</span>)}</div></div><div className="offer-end"><strong>{money(o.price_couple)}</strong><span>Internacional • casal</span><small>{o.value_score!=null?'Nota de custo-benefício: '+o.value_score+'/100 · ':''}</small><small>{o.comparable_total==null?'Total até Itália indisponível':o.total_basis!=='somente_passagem_internacional'?'Total parcial com extras manuais: '+money(o.comparable_total):'Passagem internacional: '+money(o.comparable_total)}</small><a href={o.search_url} target="_blank" rel="noreferrer"><ExternalLink size={14}/> Conferir no Google Flights</a></div></div>}
}
